321	  const vec4 D = vec4(0.0, 0.5, 1.0, 2.0);
322	  vec3 i = floor(v + dot(v, C.yyy));
323	  vec3 x0 = v - i + dot(i, C.xxx);
324	  vec3 g = step(x0.yzx, x0.xyz);
325	  vec3 l = 1.0 - g;
326	  vec3 i1 = min(g.xyz, l.zxy);
327	  vec3 i2 = max(g.xyz, l.zxy);
328	  vec3 x1 = x0 - i1 + C.xxx;
329	  vec3 x2 = x0 - i2 + 2.0 * C.xxx;
330	  vec3 x3 = x0 - 1.0 + 3.0 * C.xxx;
331	  i = mod(i, 289.0);
332	  vec4 p = permute(permute(permute(i.z + vec4(0.0, i1.z, i2.z, 1.0)) + i.y + vec4(0.0, i1.y, i2.y, 1.0)) + i.x + vec4(0.0, i1.x, i2.x, 1.0));
333	  float n_ = 1.0 / 7.0;
334	  vec3 ns = n_ * D.wyz - D.xzx;
335	  vec4 j = p - 49.0 * floor(p * ns.z * ns.z);
336	  vec4 x_ = floor(j * ns.z);
337	  vec4 y_ = floor(j - 7.0 * x_);
338	  vec4 x = x_ * ns.x + ns.yyyy;
339	  vec4 y = y_ * ns.x + ns.yyyy;
340	  vec4 h = 1.0 - abs(x) - abs(y);
341	  vec4 b0 = vec4(x.xy, y.xy);
342	  vec4 b1 = vec4(x.zw, y.zw);
343	  vec4 s0 = floor(b0) * 2.0 + 1.0;
344	  vec4 s1 = floor(b1) * 2.0 + 1.0;
345	  vec4 sh = -step(h, vec4(0.0));
346	  vec4 a0 = b0.xzyw + s0.xzyw * sh.xxyy;
347	  vec4 a1 = b1.xzyw + s1.xzyw * sh.zzww;
348	  vec3 p0 = vec3(a0.xy, h.x);
349	  vec3 p1 = vec3(a0.zw, h.y);
350	  vec3 p2 = vec3(a1.xy, h.z);
351	  vec3 p3 = vec3(a1.zw, h.w);
352	  vec4 norm = taylorInvSqrt(vec4(dot(p0, p0), dot(p1, p1), dot(p2, p2), dot(p3, p3)));
353	  p0 *= norm.x; p1 *= norm.y; p2 *= norm.z; p3 *= norm.w;
354	  vec4 m = max(0.6 - vec4(dot(x0, x0), dot(x1, x1), dot(x2, x2), dot(x3, x3)), 0.0);
355	  m = m * m;
356	  return 42.0 * dot(m * m, vec4(dot(p0, x0), dot(p1, x1), dot(p2, x2), dot(p3, x3)));
357	}
