359	float fbm(vec3 p) {
360	  float f = 0.0;
361	  float a = 0.5;
362	  for (int i = 0; i < 5; i++) {
363	    f += a * snoise(p);
364	    p = p * 2.03 + vec3(1.7, 9.2, 3.1);
365	    a *= 0.5;
366	  }
367	  return f;
368	}
