395	  vec3 navy = vec3(0.05, 0.16, 0.45);
396	  vec3 royal = vec3(0.13, 0.42, 0.98);
397	  vec3 bright = vec3(0.30, 0.60, 1.0);
398	  vec3 sky = vec3(0.66, 0.84, 1.0);
399	  vec3 lilac = vec3(0.80, 0.72, 0.98);
400	  vec3 blush = vec3(0.93, 0.80, 0.96);
