420	function compile(gl: WebGL2RenderingContext, type: number, src: string) {
421	  const sh = gl.createShader(type)!;
422	  gl.shaderSource(sh, src);
423	  gl.compileShader(sh);
424	  if (!gl.getShaderParameter(sh, gl.COMPILE_STATUS)) throw new Error(gl.getShaderInfoLog(sh) ?? "shader");
425	  return sh;
