428	export function SkyOrb({
429	  mode,
430	  getInputVolume,
431	  getOutputVolume,
432	  className,
433	}: {
434	  mode: OrbMode;
435	  getInputVolume?: () => number;
436	  getOutputVolume?: () => number;
437	  className?: string;
438	}) {
439	  const canvasRef = useRef<HTMLCanvasElement>(null);
440	  const modeRef = useRef(mode);
441	  const inRef = useRef(getInputVolume);
442	  const outRef = useRef(getOutputVolume);
443	
444	  useEffect(() => {
445	    modeRef.current = mode;
446	    inRef.current = getInputVolume;
447	    outRef.current = getOutputVolume;
448	  }, [mode, getInputVolume, getOutputVolume]);
449	
450	  useEffect(() => {
451	    const canvas = canvasRef.current;
452	    if (!canvas) return;
453	    const gl = canvas.getContext("webgl2", { premultipliedAlpha: true, antialias: true, alpha: true });
454	    if (!gl) return;
455	
456	    const prog = gl.createProgram()!;
457	    gl.attachShader(prog, compile(gl, gl.VERTEX_SHADER, VERT));
458	    gl.attachShader(prog, compile(gl, gl.FRAGMENT_SHADER, FRAG));
459	    gl.linkProgram(prog);
460	    gl.useProgram(prog);
461	
462	    const buf = gl.createBuffer();
463	    gl.bindBuffer(gl.ARRAY_BUFFER, buf);
464	    gl.bufferData(gl.ARRAY_BUFFER, new Float32Array([-1, -1, 3, -1, -1, 3]), gl.STATIC_DRAW);
465	    const loc = gl.getAttribLocation(prog, "aPos");
466	    gl.enableVertexAttribArray(loc);
467	    gl.vertexAttribPointer(loc, 2, gl.FLOAT, false, 0, 0);
468	
469	    const u = {
470	      res: gl.getUniformLocation(prog, "uRes"),
471	      time: gl.getUniformLocation(prog, "uTime"),
472	      flow: gl.getUniformLocation(prog, "uFlow"),
473	      level: gl.getUniformLocation(prog, "uLevel"),
474	      think: gl.getUniformLocation(prog, "uThink"),
475	      scale: gl.getUniformLocation(prog, "uScale"),
476	    };
477	
478	    const resize = () => {
479	      const dpr = Math.min(window.devicePixelRatio || 1, 2);
480	      const { width, height } = canvas.getBoundingClientRect();
481	      canvas.width = Math.max(1, Math.round(width * dpr));
482	      canvas.height = Math.max(1, Math.round(height * dpr));
483	      gl.viewport(0, 0, canvas.width, canvas.height);
484	    };
485	    resize();
486	    const ro = new ResizeObserver(resize);
487	    ro.observe(canvas);
488	
489	    let raf = 0;
490	    let last = performance.now();
491	    let flow = Math.random() * 100;
492	    let level = 0;
493	    let think = 0;
494	    let scale = 0.94;
495	    let time = 0;
496	
497	    const frame = (now: number) => {
498	      const dt = Math.min(0.05, (now - last) / 1000);
499	      last = now;
500	      time += dt;
501	      const m = modeRef.current;
502	      const vin = inRef.current?.() ?? 0;
503	      const vout = outRef.current?.() ?? 0;
504	
505	      const targetLevel =
506	        m === "talking" ? Math.max(vout, 0.25) : m === "listening" ? vin * 1.1 : m === "thinking" ? 0.25 + 0.15 * Math.sin(time * 3) : 0;
507	      level += (Math.min(1, targetLevel) - level) * (targetLevel > level ? 0.35 : 0.08);
508	      think += ((m === "thinking" || m === "connecting" ? 1 : 0) - think) * 0.05;
509	
510	      const breathe = m === "idle" ? 0.012 * Math.sin(time * 1.4) : 0;
511	      const targetScale = (m === "idle" ? 0.94 : 0.97) + breathe + level * 0.06;
512	      scale += (targetScale - scale) * 0.18;
513	
514	      const speed = 0.12 + level * 0.9 + think * 0.7;
515	      flow += dt * speed;
516	
517	      gl.clearColor(0, 0, 0, 0);
518	      gl.clear(gl.COLOR_BUFFER_BIT);
519	      gl.uniform2f(u.res, canvas.width, canvas.height);
520	      gl.uniform1f(u.time, time);
521	      gl.uniform1f(u.flow, flow);
522	      gl.uniform1f(u.level, level);
523	      gl.uniform1f(u.think, think);
524	      gl.uniform1f(u.scale, scale);
525	      gl.drawArrays(gl.TRIANGLES, 0, 3);
526	      raf = requestAnimationFrame(frame);
527	    };
528	    raf = requestAnimationFrame(frame);
529	
530	    return () => {
531	      cancelAnimationFrame(raf);
532	      ro.disconnect();
533	      gl.deleteProgram(prog);
534	      gl.deleteBuffer(buf);
535	    };
536	  }, []);
537	
538	  return <canvas ref={canvasRef} className={className ?? "h-full w-full"} />;
539	}
