import { Easing, interpolate, spring } from "remotion";
import voice from "./voice-data.json";

export const FPS = 30;
export const DURATION = 900;

export type Who = "shopper" | "agent";
export type LineId = keyof typeof voice;
export type Line = { id: LineId; who: Who; at: number; text: string };

export const LINES: Line[] = [
  { id: "s1", who: "shopper", at: 15, text: "Hey! Pasta night for three… and one of us is dairy-free." },
  { id: "a1", who: "agent", at: 140, text: "On it. Penne, marinara, fresh basil… and your usual Oatly." },
  { id: "s2", who: "shopper", at: 295, text: "Okay, I’m at Safeway… and they’re out of Oatly." },
  { id: "a2", who: "agent", at: 437, text: "No stress. O Organics oat milk is right there, aisle seven. Still dairy-free… and a dollar fifty cheaper." },
  { id: "s3", who: "shopper", at: 648, text: "Oh, love that. Swap it!" },
  { id: "tag", who: "agent", at: 772, text: "Basket. The shopping agent that keeps the sale." },
];

export const THINKING: Array<[number, number]> = [
  [125, 140],
  [425, 437],
];

export const T = {
  morph: 150,
  add: { penne: 168, marinara: 187, basil: 224, oatly: 258 },
  inStore: 345,
  oos: 393,
  swapIn: 425,
  pushIn: 426,
  highlight: 470,
  aisle: 525,
  dairy: 552,
  price: 590,
  tap: 718,
  collapse: 726,
  pullBack: 732,
  outro: 748,
  wordmark: 772,
  tagline: 806,
  pills: 832,
};

export const lineLength = (l: Line) => voice[l.id].frames;
export const lineEnd = (l: Line) => l.at + lineLength(l);

export function voiceAt(f: number) {
  for (const line of LINES) {
    const i = f - line.at;
    const v = voice[line.id];
    if (i >= 0 && i < v.frames) return { line, level: v.env[i], i };
  }
  return null;
}

export const thinkingAt = (f: number) => THINKING.some(([a, b]) => f >= a && f < b);

export function lastLine(f: number) {
  let found: Line | null = null;
  for (const l of LINES) if (f >= l.at) found = l;
  return found;
}

const voicedCumulative: Record<string, number[]> = {};
for (const l of LINES) {
  const env = voice[l.id].env;
  const acc: number[] = [];
  let sum = 0;
  for (const v of env) {
    sum += v > 0.08 ? 1 : 0;
    acc.push(sum);
  }
  voicedCumulative[l.id] = acc.map((x) => x / Math.max(1, sum));
}

export function wordsSpoken(l: Line, f: number) {
  const words = l.text.split(" ");
  const total = l.text.length;
  const acc = voicedCumulative[l.id];
  const i = Math.max(0, Math.min(acc.length - 1, f - l.at));
  const progress = f - l.at >= acc.length ? 1 : acc[i];
  let chars = 0;
  return words.map((w) => {
    const start = chars / total;
    chars += w.length + 1;
    return { w, on: progress + 0.02 >= start };
  });
}

export const ease = Easing.bezier(0.22, 1, 0.36, 1);
export const inOut = Easing.bezier(0.65, 0, 0.35, 1);

export const range = (f: number, a: number, b: number, from = 0, to = 1, easing = ease) =>
  interpolate(f, [a, b], [from, to], { extrapolateLeft: "clamp", extrapolateRight: "clamp", easing });

export const spr = (
  f: number,
  at: number,
  config: Partial<{ damping: number; stiffness: number; mass: number }> = { damping: 200 },
  durationInFrames?: number,
) => spring({ frame: f - at, fps: FPS, config, durationInFrames });

export const lerp = (a: number, b: number, t: number) => a + (b - a) * t;

