    lv += (Math.min(1, target) - lv) * (target > lv ? 0.58 : 0.16);
    th += ((m === "thinking" ? 1 : 0) - th) * 0.1;
    const breathe = m === "idle" ? 0.012 * Math.sin(t * 1.4) : 0;
    const targetScale = (m === "idle" ? 0.94 : 0.97) + breathe + lv * 0.06;
    sc += (targetScale - sc) * 0.33;
    fl += dt * (0.12 + lv * 0.9 + th * 0.7);
    flow[f] = fl;
    level[f] = lv;
    think[f] = th;
    scale[f] = sc;
  }
  return { flow, level, think, scale };
})();

export const orbLevel = (f: number) => SIM.level[Math.max(0, Math.min(DURATION, f))];

function compile(gl: WebGL2RenderingContext, type: number, src: string) {
  const sh = gl.createShader(type)!;
  gl.shaderSource(sh, src);
  gl.compileShader(sh);
  if (!gl.getShaderParameter(sh, gl.COMPILE_STATUS)) throw new Error(gl.getShaderInfoLog(sh) ?? "shader");
  return sh;
}

type GLState = { gl: WebGL2RenderingContext; u: Record<string, WebGLUniformLocation | null> };

export const Orb: React.FC<{ size: number; px?: number; offset?: number; style?: React.CSSProperties }> = ({
  size,
  px = 640,
  offset = 0,
  style,
}) => {
  const frame = useCurrentFrame();
  const ref = useRef<HTMLCanvasElement>(null);
  const state = useRef<GLState | null>(null);

  useLayoutEffect(() => {
    const canvas = ref.current;
    if (!canvas) return;
    if (!state.current) {
      const gl = canvas.getContext("webgl2", { premultipliedAlpha: true, antialias: true, alpha: true, preserveDrawingBuffer: true });
      if (!gl) return;
      const prog = gl.createProgram()!;
      gl.attachShader(prog, compile(gl, gl.VERTEX_SHADER, VERT));
      gl.attachShader(prog, compile(gl, gl.FRAGMENT_SHADER, FRAG));
      gl.linkProgram(prog);
      gl.useProgram(prog);
      const buf = gl.createBuffer();
      gl.bindBuffer(gl.ARRAY_BUFFER, buf);
      gl.bufferData(gl.ARRAY_BUFFER, new Float32Array([-1, -1, 3, -1, -1, 3]), gl.STATIC_DRAW);
      const loc = gl.getAttribLocation(prog, "aPos");
      gl.enableVertexAttribArray(loc);
      gl.vertexAttribPointer(loc, 2, gl.FLOAT, false, 0, 0);
      const u = Object.fromEntries(
        ["uRes", "uTime", "uFlow", "uLevel", "uThink", "uScale"].map((k) => [k, gl.getUniformLocation(prog, k)]),
      );
      state.current = { gl, u };
    }
    const { gl, u } = state.current;
    const f = Math.max(0, Math.min(DURATION, frame + offset));
    gl.viewport(0, 0, canvas.width, canvas.height);
    gl.clearColor(0, 0, 0, 0);
    gl.clear(gl.COLOR_BUFFER_BIT);
    gl.uniform2f(u.uRes, canvas.width, canvas.height);
    gl.uniform1f(u.uTime, f / FPS);
    gl.uniform1f(u.uFlow, SIM.flow[f]);
    gl.uniform1f(u.uLevel, SIM.level[f]);
    gl.uniform1f(u.uThink, SIM.think[f]);
    gl.uniform1f(u.uScale, SIM.scale[f]);
    gl.drawArrays(gl.TRIANGLES, 0, 3);
  }, [frame, offset]);

  return <canvas ref={ref} width={px} height={px} style={{ width: size, height: size, display: "block", ...style }} />;
};
