import { interpolateColors, useCurrentFrame } from "remotion";
import { Orb, orbModeAt } from "./orb";
import { T, lastLine, lerp, range, spr, thinkingAt, wordsSpoken } from "./timeline";
import { C, Icon, P, Product, Thumb, money, sans, serif } from "./ui";

export const SW = 393;
export const SH = 852;
const CONTENT_TOP = 150;
const FULFILL_H = 124;
const SWAP_TOP = FULFILL_H + 16;
const SWAP_H = 377;
const ROW = 68;
const AISLE_H = 30;

export const SWAP_FOCUS = { x: SW / 2, y: CONTENT_TOP + SWAP_TOP + SWAP_H / 2 };

const ITEMS = ["penne", "marinara", "basil", "oatly"] as const;
type Item = (typeof ITEMS)[number];
const DELIVERY_Y: Record<Item, number> = { penne: 0, marinara: ROW, basil: ROW * 2, oatly: ROW * 3 };
const STORE_Y: Record<Item, number> = {
  basil: AISLE_H,
  oatly: AISLE_H * 2 + ROW,
  penne: AISLE_H * 3 + ROW * 2,
