];
const STORE_LIST_H = AISLE_H * 3 + ROW * 4;

const statusText = (f: number) =>
  thinkingAt(f) ? "Checking the shelves…" : orbModeAt(f) === "talking" ? "Speaking" : "Listening";

function captionText(f: number) {
  const l = lastLine(f);
  if (!l || l.id === "tag") return null;
  let words = wordsSpoken(l, f)
    .filter((w) => w.on)
    .map((w) => w.w);
  let clipped = false;
  while (words.join(" ").length > 74) {
    words = words.slice(1);
    clipped = true;
  }
  const text = (clipped ? "… " : "") + words.join(" ");
  return { who: l.who, text, at: l.at };
}

const Status: React.FC<{ f: number; align: "left" | "center"; size: number; width: number }> = ({ f, align, size, width }) => {
  const cap = captionText(f);
  const pulse = 0.55 + 0.45 * Math.sin(f / 4);
  return (
    <div style={{ width, textAlign: align }}>
      <p style={{ margin: 0, fontSize: 14, fontWeight: 500, color: C.navy, display: "flex", alignItems: "center", gap: 6, justifyContent: align === "center" ? "center" : "flex-start" }}>
        <span style={{ width: 6, height: 6, borderRadius: 9, background: C.navy, opacity: pulse }} />
