      <p style={{ margin: 0, fontSize: 15, fontWeight: 500, lineHeight: 1.2, whiteSpace: "nowrap", overflow: "hidden", textOverflow: "ellipsis", color: interpolateColors(oos, [0, 1], [C.ink, C.subtle]) }}>
        <span style={{ position: "relative" }}>
