const OrderCard: React.FC<{ f: number; store: number; top: number }> = ({ f, store, top }) => {
  const added = Object.fromEntries(ITEMS.map((k) => [k, spr(f, T.add[k], { damping: 20, stiffness: 170 })])) as Record<Item, number>;
  const count = ITEMS.filter((k) => f >= T.add[k]).length;
  const deliveryH = ITEMS.reduce((h, k) => h + ROW * Math.min(1, added[k] * 1.15), 0);
  const listH = lerp(deliveryH, STORE_LIST_H, store);
  const oos = spr(f, T.oos, { damping: 16, stiffness: 220 });
  const swapped = spr(f, T.collapse + 4, { damping: 20, stiffness: 160 });
  const flash = range(f, T.oos, T.oos + 4) * (1 - range(f, T.oos + 8, T.oos + 40));
  const swapFlash = range(f, T.collapse + 4, T.collapse + 8) * (1 - range(f, T.collapse + 12, T.collapse + 44));

  return (
    <div style={{ position: "absolute", left: 20, top, width: 353, height: 56 + listH + 14, background: "#fff", border: `1px solid ${C.hairline}`, borderRadius: 32, boxSizing: "border-box", overflow: "hidden" }}>
      <div style={{ position: "absolute", left: 20, right: 20, top: 20, display: "flex", alignItems: "baseline", justifyContent: "space-between" }}>
