              )}
              <div style={{ position: "absolute", left: 0, top: 22, width: 24, height: 24, borderRadius: 99, border: `1.5px solid ${C.hairline}`, background: "#fff", boxSizing: "border-box", opacity: store * (isOat ? 1 - 0.7 * oos * (1 - swapped) : 1) }} />
              <div style={{ position: "absolute", top: 0, bottom: 0, right: 0, left: 38 * store }}>
                {isOat ? (
                  <>
                    <div style={{ position: "absolute", inset: 0, opacity: 1 - swapped, transform: `translateX(${-28 * swapped}px)` }}>
                      <RowBody p={P.oatly} store={store} oos={f >= T.oos ? oos : 0} />
                    </div>
                    {swapped > 0.001 && (
                      <div style={{ position: "absolute", inset: 0, opacity: swapped, transform: `translateX(${28 * (1 - swapped)}px)` }}>
                        <RowBody p={P.oorganics} store={store} swapped={spr(f, T.collapse + 10, { damping: 14, stiffness: 200 })} />
                      </div>
