const OptionCard: React.FC<{ f: number; p: Product; first?: boolean; diff: string; left: number }> = ({ f, p, first, diff, left }) => {
  const glow = first ? spr(f, T.highlight, { damping: 18, stiffness: 120 }) : 0;
