          <span style={{ position: "absolute", left: -3, right: -3, top: -1, bottom: -1, borderRadius: 4, background: C.sky, opacity: 0.55, transform: `scaleX(${mark})`, transformOrigin: "left", zIndex: -1 }} />
          Aisle 7
        </span>
      </p>
      <div style={{ height: 20, marginTop: 6 }}>
        <span
          style={{
            display: "inline-flex",
            alignItems: "center",
            gap: 4,
            padding: "2px 7px",
            borderRadius: 99,
            fontSize: 11,
            fontWeight: 500,
            background: first ? C.greenBg : C.surface,
            color: first ? C.green : C.subtle,
            opacity: first ? dairy : 1,
            transform: `scale(${first ? 0.6 + 0.4 * dairy : 1})`,
            transformOrigin: "left center",
          }}
        >
          <Icon name="check" size={10} stroke={3} />
          Dairy-free
        </span>
      </div>
      <div style={{ marginTop: 8, display: "flex", alignItems: "center", justifyContent: "space-between" }}>
        <span style={{ fontSize: 14, fontWeight: 500, fontVariantNumeric: "tabular-nums" }}>{money(p.price)}</span>
        <span
          style={{
            position: "relative",
            fontSize: 11.5,
            color: C.green,
            fontWeight: priceMark > 0.5 ? 600 : 400,
            transform: `scale(${1 + 0.28 * pricePulse})`,
            transformOrigin: "right center",
          }}
        >
          <span style={{ position: "absolute", left: -4, right: -4, top: -2, bottom: -2, borderRadius: 5, background: C.greenBg, transform: `scaleX(${priceMark})`, transformOrigin: "right", zIndex: -1 }} />
          {diff}
        </span>
      </div>
      <div
        style={{
          marginTop: 10,
          height: 30,
          borderRadius: 99,
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          fontSize: 13,
          fontWeight: 500,
          background: first ? interpolateColors(press, [0, 1], [C.navy, "#050f33"]) : C.surface,
          color: first ? "#fff" : C.ink,
          transform: `scale(${1 - 0.06 * press})`,
        }}
      >
        Swap
      </div>
    </div>
  );
};

const SwapCard: React.FC<{ f: number; open: number }> = ({ f, open }) => {
  const chip = spr(f, T.swapIn + 6, { damping: 12, stiffness: 220 });
  const opts = [
    { p: P.oorganics, diff: "$1.50 less", first: true },
    { p: P.califia, diff: "$0.50 less" },
    { p: P.pacific, diff: "$1.60 less" },
  ];
  return (
    <div style={{ position: "absolute", left: 20, top: SWAP_TOP, width: 353, height: SWAP_H * Math.min(1, open), overflow: "hidden", borderRadius: 32 }}>
      <div
        style={{
          position: "absolute",
          inset: 0,
          height: SWAP_H,
          boxSizing: "border-box",
          background: "#fff",
          border: `1px solid ${C.hairline}`,
          borderRadius: 32,
          opacity: Math.min(1, open * 1.5),
          transform: `translateY(${(1 - open) * 18}px) scale(${0.98 + 0.02 * open})`,
        }}
      >
        <div style={{ position: "absolute", left: 20, top: 20, width: 250 }}>
          <p style={{ margin: 0, fontSize: 11, fontWeight: 600, letterSpacing: "0.12em", textTransform: "uppercase", color: C.oosInk }}>Not on the shelf</p>
          <p style={{ margin: "4px 0 0", fontFamily: serif, fontSize: 22, lineHeight: 1.12, fontWeight: 500, letterSpacing: "-0.02em", color: C.ink }}>{P.oatly.name}</p>
        </div>
        <span style={{ position: "absolute", right: 20, top: 20, fontSize: 13, color: C.subtle }}>Skip</span>
        <div style={{ position: "absolute", left: 20, top: 92, display: "flex", alignItems: "center", gap: 8 }}>
          <span
            style={{
              display: "inline-flex",
              alignItems: "center",
              gap: 4,
              padding: "3px 9px 3px 7px",
              borderRadius: 99,
              background: C.navy,
              color: "#fff",
              fontSize: 11.5,
              fontWeight: 600,
              transform: `scale(${0.5 + 0.5 * chip})`,
              opacity: Math.min(1, chip * 2),
              transformOrigin: "left center",
            }}
          >
            <Icon name="zap" size={11} color="#ffd75e" stroke={2.4} />
            Found in 4 ms
          </span>
          <span style={{ fontSize: 12, color: C.subtle, opacity: chip }}>3 in stock nearby</span>
        </div>
        <div style={{ position: "absolute", left: 20, top: 124, width: 333, height: 240 }}>
          {opts.map((o, i) => {
            const t = spr(f, T.swapIn + 4 + i * 4, { damping: 18, stiffness: 180 });
            return (
              <div key={o.p.id} style={{ opacity: Math.min(1, t * 1.4), transform: `translateX(${(1 - t) * 40}px)` }}>
                <OptionCard f={f} p={o.p} first={o.first} diff={o.diff} left={i * 160} />
              </div>
            );
          })}
        </div>
      </div>
    </div>
  );
};

const CheckoutBar: React.FC<{ f: number; store: number; enter: number }> = ({ f, store, enter }) => {
  const swapped = spr(f, T.collapse + 4, { damping: 200 }, 20);
  const subtotal = ITEMS.reduce((s, k) => {
    const t = range(f, T.add[k], T.add[k] + 12);
    const unit = k === "oatly" ? lerp(P.oatly.price, P.oorganics.price, swapped) : P[k].price;
    return s + unit * P[k].qty * t;
  }, 0);
  const qty = ITEMS.filter((k) => f >= T.add[k]).reduce((n, k) => n + P[k].qty, 0);
  return (
    <div style={{ position: "absolute", left: 20, top: SH - 34 - 68, width: 353, height: 68, transform: `translateY(${(1 - enter) * 110}px)`, opacity: enter }}>
      <div
        style={{
          position: "absolute",
          inset: 0,
          borderRadius: 999,
          border: "1px solid #c9ced8",
          background: "rgba(255,255,255,0.95)",
          boxShadow: "0 18px 40px -18px rgba(11,31,91,0.35)",
          boxSizing: "border-box",
        }}
      />
      {[
        { o: 1 - store, label: "Checkout on Instacart", sub: `${money(subtotal)} · ${qty} items`, icon: "upRight" as const },
        { o: store, label: "Finish shopping", sub: `${money(subtotal)} · 0 of 4 picked`, icon: "right" as const },
      ].map((v) => (
        <div key={v.label} style={{ position: "absolute", inset: 0, opacity: v.o }}>
          <div style={{ position: "absolute", left: 28, top: 14, lineHeight: 1.25 }}>
            <p style={{ margin: 0, fontSize: 16, fontWeight: 500, color: C.ink }}>{v.label}</p>
            <p style={{ margin: 0, fontSize: 13, color: C.subtle, fontVariantNumeric: "tabular-nums" }}>{v.sub}</p>
          </div>
          <div style={{ position: "absolute", right: 10, top: 10, width: 48, height: 48, borderRadius: 99, background: C.navy, display: "flex", alignItems: "center", justifyContent: "center" }}>
            <Icon name={v.icon} size={20} color="#fff" />
          </div>
        </div>
      ))}
    </div>
  );
};

const Tap: React.FC<{ f: number; at: number; x: number; y: number }> = ({ f, at, x, y }) => {
  if (f < at - 10 || f > at + 24) return null;
  const inT = range(f, at - 10, at - 2);
  const press = Math.sin(Math.PI * range(f, at - 2, at + 6, 0, 1, (v) => v));
  const out = range(f, at + 8, at + 20);
  const ring = range(f, at, at + 18);
  return (
    <>
      <div
        style={{
          position: "absolute",
          left: x - 30,
          top: y - 30,
          width: 60,
          height: 60,
          borderRadius: 99,
          border: "2px solid rgba(11,31,91,0.5)",
          transform: `scale(${0.6 + ring * 1.4})`,
          opacity: (1 - ring) * (f >= at ? 1 : 0),
        }}
      />
      <div
        style={{
          position: "absolute",
          left: x - 22,
          top: y - 22,
          width: 44,
          height: 44,
          borderRadius: 99,
          background: "rgba(255,255,255,0.55)",
          border: "1.5px solid rgba(255,255,255,0.9)",
          boxShadow: "0 6px 20px rgba(11,31,91,0.35), inset 0 0 12px rgba(11,31,91,0.15)",
          transform: `scale(${(0.5 + 0.5 * inT) * (1 - 0.18 * press)})`,
          opacity: inT * (1 - out),
        }}
      />
    </>
  );
};

const StatusBar: React.FC = () => (
  <div style={{ position: "absolute", left: 0, right: 0, top: 0, height: 54, zIndex: 30 }}>
    <span style={{ position: "absolute", left: 50, top: 18, fontSize: 17, fontWeight: 600, color: C.ink, letterSpacing: "-0.01em" }}>9:41</span>
    <div style={{ position: "absolute", left: (SW - 124) / 2, top: 11, width: 124, height: 36, borderRadius: 20, background: "#000" }} />
    <div style={{ position: "absolute", right: 30, top: 21, display: "flex", alignItems: "center", gap: 6 }}>
      <svg width="18" height="12" viewBox="0 0 18 12">
        {[0, 1, 2, 3].map((i) => (
          <rect key={i} x={i * 5} y={9 - i * 3} width="3.2" height={3 + i * 3} rx="0.8" fill={C.ink} />
        ))}
      </svg>
      <svg width="16" height="12" viewBox="0 0 16 12" fill={C.ink}>
        <path d="M8 2.2c2.3 0 4.4.9 6 2.4l1.2-1.3A10.4 10.4 0 0 0 8 .4 10.4 10.4 0 0 0 .8 3.3L2 4.6a8.6 8.6 0 0 1 6-2.4Z" />
        <path d="M8 5.6c1.4 0 2.6.5 3.6 1.4l1.2-1.3A7 7 0 0 0 8 3.8a7 7 0 0 0-4.8 1.9L4.4 7A5.2 5.2 0 0 1 8 5.6Z" />
        <path d="M8 9c.5 0 1 .2 1.3.5L8 11 6.7 9.5c.3-.3.8-.5 1.3-.5Z" />
      </svg>
      <svg width="27" height="13" viewBox="0 0 27 13">
        <rect x="0.5" y="0.5" width="23" height="12" rx="3.8" fill="none" stroke={C.ink} strokeOpacity="0.4" />
        <rect x="2" y="2" width="20" height="9" rx="2.5" fill={C.ink} />
        <path d="M25 4.5v4c.8-.3 1.4-1.1 1.4-2s-.6-1.7-1.4-2Z" fill={C.ink} fillOpacity="0.45" />
      </svg>
    </div>
  </div>
);

export const Screen: React.FC = () => {
  const f = useCurrentFrame();
  const morph = spr(f, T.morph, { damping: 200 }, 28);
  const store = spr(f, T.inStore, { damping: 24, stiffness: 140 });
  const open = spr(f, T.swapIn, { damping: 22, stiffness: 150 }) - spr(f, T.collapse, { damping: 200 }, 20);
  const enter = spr(f, T.morph + 10, { damping: 22, stiffness: 160 });

  const orbSize = lerp(224, 64, morph);
  const orbX = lerp(SW / 2, 20 + 32, morph);
  const orbY = lerp(468, 66 + 32, morph);

  return (
    <div style={{ position: "absolute", inset: 0, overflow: "hidden", fontFamily: sans, color: C.ink, background: "linear-gradient(180deg,#edf1f7 0%,#f3f5f8 45%,#f5f5f6 100%)" }}>
      <StatusBar />

      <div style={{ position: "absolute", left: 0, right: 0, top: 148, textAlign: "center", opacity: 1 - range(morph, 0, 0.45), transform: `translateY(${-30 * morph}px)` }}>
        <h1 style={{ margin: 0, fontFamily: serif, fontSize: 52, lineHeight: 0.95, fontWeight: 500, letterSpacing: "-0.035em", color: C.ink }}>
          What’s for
          <br />
          dinner?
        </h1>
        <p style={{ margin: "16px 0 0", fontSize: 17, color: C.body }}>Just say it. Your order builds itself.</p>
      </div>

      <div style={{ position: "absolute", left: (SW - 330) / 2, top: 606, opacity: 1 - range(morph, 0, 0.35) }}>
        <Status f={f} align="center" size={17} width={330} />
      </div>

      <div style={{ position: "absolute", left: 0, right: 0, top: CONTENT_TOP, bottom: 0, opacity: range(morph, 0.2, 1), transform: `translateY(${(1 - morph) * 40}px)` }}>
        <Fulfillment f={f} store={store} />
        {open > 0.001 && <SwapCard f={f} open={open} />}
        <OrderCard f={f} store={store} top={SWAP_TOP + (SWAP_H + 16) * Math.max(0, open)} />
      </div>

      <div style={{ position: "absolute", left: 0, right: 0, top: 0, height: 146, background: "rgba(238,242,247,0.86)", backdropFilter: "blur(18px)", opacity: range(morph, 0.3, 1), zIndex: 10 }} />
      <div style={{ position: "absolute", left: 100, top: 72, zIndex: 12, opacity: range(morph, 0.5, 1) }}>
        <Status f={f} align="left" size={15} width={273} />
      </div>

      <div style={{ position: "absolute", left: orbX - orbSize / 2, top: orbY - orbSize / 2, zIndex: 11 }}>
        <div style={{ position: "absolute", inset: -orbSize * 0.18, borderRadius: 999, background: "radial-gradient(circle, rgba(48,110,255,0.22) 0%, rgba(48,110,255,0) 65%)" }} />
        <Orb size={orbSize} px={560} />
      </div>

      <CheckoutBar f={f} store={store} enter={enter} />
      <Tap f={f} at={T.tap} x={20 + 20 + 75} y={CONTENT_TOP + SWAP_TOP + 124 + 195} />
      <div style={{ position: "absolute", left: (SW - 134) / 2, bottom: 8, width: 134, height: 5, borderRadius: 9, background: C.ink, zIndex: 30 }} />
    </div>
  );
};

export const IPhone: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const B = 13;
  const W = SW + B * 2;
