      {btn("left", 330, 64)}
      {btn("right", 280, 100)}
      <div
        style={{
          position: "absolute",
          inset: 0,
          borderRadius: 72,
          padding: 3,
          background: "linear-gradient(135deg,#e6e8ec 0%,#9aa0a8 22%,#f1f2f4 48%,#868c95 74%,#d6d9de 100%)",
          boxShadow: "0 60px 120px -40px rgba(11,31,91,0.55), 0 30px 60px -30px rgba(10,15,28,0.45)",
        }}
      >
        <div style={{ position: "relative", width: W, height: H, borderRadius: 69, background: "#06070a" }}>
          <div style={{ position: "absolute", left: B, top: B, width: SW, height: SH, borderRadius: 56, overflow: "hidden", isolation: "isolate" }}>
