import { Audio } from "@remotion/media";
import { AbsoluteFill, Sequence, staticFile, useCurrentFrame } from "remotion";
import { Orb, orbLevel } from "./orb";
import { IPhone, SH, SW, SWAP_FOCUS, Screen } from "./phone";
import { DURATION, LINES, T, ease, lerp, lineEnd, range, spr, voiceAt, wordsSpoken } from "./timeline";
import { C, Icon, sans, serif } from "./ui";

const PHONE_W = SW + 32;
const PHONE_H = SH + 32;
const BASE = { cx: 1200, cy: 540, s: 1.06 };
const ZOOM = 1.5;

function camera(f: number) {
  const entry = spr(f, 0, { damping: 200 }, 34);
  const pIn = spr(f, T.pushIn, { damping: 200 }, 40) * (1 - spr(f, T.pullBack, { damping: 200 }, 34));
  const pOut = spr(f, T.outro, { damping: 200 }, 46);
  const focusDy = (16 + SWAP_FOCUS.y - PHONE_H / 2) * BASE.s * ZOOM;
  let s = lerp(BASE.s, BASE.s * ZOOM, pIn);
  let cx = lerp(BASE.cx, 1150, pIn);
  let cy = lerp(BASE.cy, 540 - focusDy + 20, pIn);
  s = lerp(s, 0.98, pOut);
  cx = lerp(cx, 1330, pOut);
  cy = lerp(cy, 540, pOut);
  const shake = f >= T.oos ? Math.sin(f * 2.4) * 8 * (1 - range(f, T.oos, T.oos + 16, 0, 1, (x) => x)) : 0;
  const bump = 1 + 0.025 * Math.sin(Math.PI * range(f, T.tap + 1, T.tap + 16, 0, 1, (x) => x));
  const rotY = lerp(-9, -2, range(f, 0, 280)) * (1 - pIn) + lerp(0, -16, pOut) + Math.sin(f / 55) * 1.4;
  const rotX = lerp(26, 4, entry) * (1 - pIn) + lerp(0, 3, pOut);
  return {
    cx: cx + shake,
    cy: cy + (1 - entry) * 620 + Math.sin(f / 38) * 5,
    s: s * bump * lerp(0.92, 1, entry),
    rotY,
    rotX,
    entry,
  };
}

const Backdrop: React.FC<{ f: number }> = ({ f }) => {
  const cam = camera(f);
  const lv = orbLevel(f);
  const oosFlash = f >= T.oos ? range(f, T.oos, T.oos + 3) * (1 - range(f, T.oos + 6, T.oos + 40)) : 0;
  const blob = (x: number, y: number, r: number, color: string, k: number) => (
    <div
      style={{
        position: "absolute",
        left: x + Math.sin(f / (60 + k * 7) + k) * 60 - r,
        top: y + Math.cos(f / (70 + k * 5) + k) * 50 - r,
        width: r * 2,
        height: r * 2,
        borderRadius: "50%",
        background: `radial-gradient(circle, ${color} 0%, rgba(255,255,255,0) 68%)`,
      }}
    />
  );
  return (
    <AbsoluteFill style={{ background: "linear-gradient(180deg,#e9eef6 0%,#f3f5f8 55%,#f7f7f8 100%)", overflow: "hidden" }}>
      {blob(1500, 200, 620, "rgba(150,200,255,0.55)", 1)}
      {blob(260, 900, 640, "rgba(204,184,250,0.42)", 2)}
      {blob(900, -120, 520, "rgba(238,204,245,0.35)", 3)}
      <AbsoluteFill
        style={{
          backgroundImage: "radial-gradient(rgba(11,31,91,0.10) 1.1px, transparent 1.4px)",
          backgroundSize: "30px 30px",
          backgroundPosition: `${(f * 0.25) % 30}px ${(f * 0.12) % 30}px`,
          maskImage: "radial-gradient(ellipse 70% 70% at 55% 50%, black 0%, transparent 75%)",
          WebkitMaskImage: "radial-gradient(ellipse 70% 70% at 55% 50%, black 0%, transparent 75%)",
        }}
      />
      <div
        style={{
          position: "absolute",
          left: cam.cx - 520,
          top: cam.cy - 520,
          width: 1040,
          height: 1040,
          borderRadius: "50%",
          background: "radial-gradient(circle, rgba(48,110,255,0.32) 0%, rgba(120,170,255,0.12) 38%, rgba(255,255,255,0) 66%)",
          opacity: (0.35 + 0.65 * lv) * cam.entry,
          transform: `scale(${0.9 + lv * 0.18})`,
        }}
      />
      <AbsoluteFill style={{ background: `radial-gradient(circle at ${cam.cx}px ${cam.cy}px, rgba(220,40,30,0.22) 0%, rgba(220,40,30,0) 55%)`, opacity: oosFlash }} />
    </AbsoluteFill>
  );
};

const BigType: React.FC<{ f: number }> = ({ f }) => {
  const o = range(f, T.swapIn, T.swapIn + 14) * (1 - range(f, T.pullBack - 10, T.pullBack + 6));
  if (o <= 0) return null;
  return (
    <div
      style={{
        position: "absolute",
        left: 0,
        right: 0,
        top: 120,
        textAlign: "center",
        fontFamily: serif,
        fontStyle: "italic",
        fontSize: 620,
        lineHeight: 1,
        letterSpacing: "-0.06em",
        color: "transparent",
        WebkitTextStroke: "2px rgba(11,31,91,0.12)",
        opacity: o,
        transform: `translateX(${80 - range(f, T.swapIn, T.pullBack, 0, 160, (x) => x)}px) scale(${0.94 + 0.08 * range(f, T.swapIn, T.pullBack, 0, 1, (x) => x)})`,
      }}
    >
      4 ms
    </div>
  );
};

const Ripple: React.FC<{ f: number; at: number }> = ({ f, at }) => {
  if (f < at || f > at + 40) return null;
  const cam = camera(f);
  return (
    <>
      {[0, 7].map((d) => {
        const t = range(f, at + d, at + d + 30, 0, 1, ease);
        return (
          <div
            key={d}
            style={{
              position: "absolute",
              left: cam.cx - 300,
              top: cam.cy - 300,
              width: 600,
              height: 600,
              borderRadius: "50%",
              border: "3px solid rgba(48,110,255,0.5)",
              transform: `scale(${0.6 + t * 1.8})`,
              opacity: (1 - t) * (f >= at + d ? 1 : 0),
            }}
          />
        );
      })}
    </>
  );
};

const BEATS = [
  { from: 4, to: 288, n: "01", eyebrow: "Talk to your grocer", a: "Just say", b: "what’s for dinner." },
  { from: 292, to: 428, n: "02", eyebrow: "In the aisle", a: "Shelf’s empty?", b: "Happens." },
  { from: 430, to: 642, n: "03", eyebrow: "Instant substitutes", a: "The right swap,", b: "in 4 ms." },
  { from: 646, to: 742, n: "04", eyebrow: "Revenue kept", a: "Sale saved.", b: "Shopper happy." },
];

const Words: React.FC<{ f: number; at: number; text: string; style: React.CSSProperties; stagger?: number }> = ({ f, at, text, style, stagger = 3 }) => (
  <span style={{ display: "block", overflow: "hidden", paddingBottom: "0.12em", marginBottom: "-0.12em", ...style }}>
    {text.split(" ").map((w, i) => {
      const t = spr(f, at + i * stagger, { damping: 20, stiffness: 140 });
      return (
        <span key={i} style={{ display: "inline-block", transform: `translateY(${(1 - t) * 110}%) rotate(${(1 - t) * 4}deg)`, opacity: Math.min(1, t * 2), marginRight: "0.24em" }}>
          {w}
        </span>
      );
    })}
  </span>
);

const Headline: React.FC<{ f: number }> = ({ f }) => (
  <>
    {BEATS.map((b) => {
      if (f < b.from || f > b.to + 2) return null;
      const out = range(f, b.to - 10, b.to);
      const line = range(f, b.from, b.from + 18);
      return (
        <div key={b.n} style={{ position: "absolute", left: 140, top: 262, width: 720, opacity: 1 - out, transform: `translateY(${-24 * out}px)`, filter: `blur(${out * 6}px)` }}>
          <div style={{ display: "flex", alignItems: "center", gap: 14, marginBottom: 26 }}>
            <span
              style={{
                width: 40,
                height: 40,
                borderRadius: 99,
                background: C.navy,
                color: "#fff",
                fontSize: 15,
                fontWeight: 600,
                display: "flex",
                alignItems: "center",
                justifyContent: "center",
                transform: `scale(${spr(f, b.from, { damping: 12, stiffness: 200 })})`,
              }}
            >
              {b.n}
            </span>
            <span style={{ height: 1.5, width: 48 * line, background: C.navy, opacity: 0.4 }} />
            <span style={{ fontSize: 18, fontWeight: 500, letterSpacing: "0.16em", textTransform: "uppercase", color: C.body, opacity: line }}>{b.eyebrow}</span>
          </div>
          <Words f={f} at={b.from + 3} text={b.a} style={{ fontFamily: serif, fontSize: 96, lineHeight: 0.98, fontWeight: 500, letterSpacing: "-0.035em", color: C.ink }} />
          <Words f={f} at={b.from + 9} text={b.b} style={{ fontFamily: serif, fontStyle: "italic", fontSize: 96, lineHeight: 0.98, fontWeight: 500, letterSpacing: "-0.035em", color: C.navy }} />
        </div>
      );
    })}
  </>
);

const Speaker: React.FC<{ who: "shopper" | "agent" }> = ({ who }) =>
  who === "agent" ? (
    <span style={{ width: 34, height: 34, borderRadius: 99, background: "radial-gradient(circle at 30% 30%, #a9d6ff 0%, #3c7bff 38%, #0d2a78 72%, #c9b8fa 100%)", boxShadow: "0 4px 14px -4px rgba(48,110,255,0.7)" }} />
  ) : (
    <span style={{ width: 34, height: 34, borderRadius: 99, background: "#e3e8f1", display: "flex", alignItems: "center", justifyContent: "center", color: C.body }}>
      <Icon name="user" size={18} stroke={2} />
    </span>
  );

const Subtitles: React.FC<{ f: number }> = ({ f }) => (
  <>
    {LINES.filter((l) => l.id !== "tag").map((l) => {
      const end = lineEnd(l);
      if (f < l.at - 4 || f > end + 16) return null;
      const o = range(f, l.at - 4, l.at + 4) * (1 - range(f, end + 4, end + 16));
      const words = wordsSpoken(l, f);
      return (
        <div key={l.id} style={{ position: "absolute", left: 140, top: 630, width: 640, opacity: o, transform: `translateY(${(1 - range(f, l.at - 4, l.at + 8)) * 14}px)` }}>
          <div style={{ display: "flex", alignItems: "center", gap: 12, marginBottom: 14 }}>
            <Speaker who={l.who} />
            <span style={{ fontSize: 16, fontWeight: 600, letterSpacing: "0.14em", textTransform: "uppercase", color: l.who === "agent" ? C.navy : C.body }}>
              {l.who === "agent" ? "Basket" : "Shopper"}
            </span>
          </div>
          <p style={{ margin: 0, fontSize: 36, lineHeight: 1.28, fontWeight: 500, letterSpacing: "-0.01em", color: C.ink }}>
            {words.map((w, i) => (
              <span key={i} style={{ opacity: w.on ? 1 : 0.16 }}>
                {w.w}{" "}
              </span>
            ))}
          </p>
        </div>
      );
    })}
  </>
);

const CALLOUTS = [
  { at: T.oos + 6, icon: "alert" as const, tone: C.oosInk, bg: C.oos, title: "Out of stock, flagged", sub: "Restock signal sent to the store" },
  { at: T.swapIn + 6, icon: "zap" as const, tone: C.navy, bg: "#e6ecf9", title: "Substitutes in 4 ms", sub: "Moss search · no LLM in the hot path" },
  { at: T.highlight, icon: "store" as const, tone: C.navy, bg: "#e6ecf9", title: "Store brand ranked first", sub: "Better margin for the grocer" },
  { at: T.dairy, icon: "leaf" as const, tone: C.green, bg: C.greenBg, title: "Diet respected", sub: "Still dairy-free for the household" },
  { at: T.price, icon: "trend" as const, tone: C.green, bg: C.greenBg, title: "$1.50 cheaper", sub: "And the sale stays in the store" },
];

const Callouts: React.FC<{ f: number }> = ({ f }) => (
  <>
    {CALLOUTS.map((c, i) => {
      if (f < c.at) return null;
      const t = spr(f, c.at, { damping: 18, stiffness: 160 });
      const out = range(f, T.pullBack - 6 + i * 2, T.pullBack + 6 + i * 2);
      return (
        <div
          key={c.title}
          style={{
            position: "absolute",
            left: 1548,
            top: 236 + i * 118,
            width: 330,
            boxSizing: "border-box",
            padding: "18px 20px",
            display: "flex",
            gap: 16,
            alignItems: "center",
            borderRadius: 24,
            background: "rgba(255,255,255,0.88)",
            border: `1px solid ${C.hairline}`,
            boxShadow: "0 20px 40px -24px rgba(11,31,91,0.35)",
            opacity: Math.min(1, t * 1.6) * (1 - out),
            transform: `translateX(${(1 - t) * 60 + out * 40}px) scale(${0.94 + 0.06 * t})`,
          }}
        >
          <span style={{ width: 44, height: 44, borderRadius: 14, background: c.bg, color: c.tone, display: "flex", alignItems: "center", justifyContent: "center", flexShrink: 0 }}>
            <Icon name={c.icon} size={22} stroke={2.1} />
          </span>
          <span>
            <span style={{ display: "block", fontSize: 21, fontWeight: 600, color: C.ink, letterSpacing: "-0.01em" }}>{c.title}</span>
            <span style={{ display: "block", marginTop: 3, fontSize: 15.5, color: C.subtle }}>{c.sub}</span>
          </span>
        </div>
      );
    })}
  </>
);

const PILLS = [
  { icon: "trend" as const, text: "+$3.99 sale kept" },
  { icon: "zap" as const, text: "4 ms substitutes" },
  { icon: "store" as const, text: "Restock signal sent" },
];

const Outro: React.FC<{ f: number }> = ({ f }) => {
  if (f < T.outro) return null;
  const orb = spr(f, T.wordmark - 6, { damping: 13, stiffness: 140 });
  const letters = "Basket".split("");
  return (
    <div style={{ position: "absolute", left: 140, top: 250, width: 900 }}>
      <div style={{ display: "flex", alignItems: "center", gap: 30 }}>
        <div style={{ width: 128, height: 128, transform: `scale(${orb})`, opacity: Math.min(1, orb * 2) }}>
          <Orb size={128} px={384} />
        </div>
        <div style={{ fontFamily: serif, fontSize: 176, lineHeight: 1, fontWeight: 500, letterSpacing: "-0.045em", color: C.ink, display: "flex", overflow: "hidden", paddingBottom: 14, marginBottom: -14 }}>
          {letters.map((ch, i) => {
            const t = spr(f, T.wordmark + i * 2, { damping: 18, stiffness: 150 });
            return (
              <span key={i} style={{ display: "inline-block", transform: `translateY(${(1 - t) * 100}%)`, opacity: Math.min(1, t * 2), filter: `blur(${(1 - Math.min(1, t)) * 8}px)` }}>
                {ch}
              </span>
            );
          })}
        </div>
      </div>
      <div style={{ marginTop: 34 }}>
        <Words f={f} at={T.tagline} stagger={2} text="The shopping agent" style={{ fontFamily: serif, fontSize: 64, lineHeight: 1.04, fontWeight: 500, letterSpacing: "-0.03em", color: C.ink }} />
        <Words f={f} at={T.tagline + 8} stagger={2} text="that keeps the sale." style={{ fontFamily: serif, fontStyle: "italic", fontSize: 64, lineHeight: 1.04, fontWeight: 500, letterSpacing: "-0.03em", color: C.navy }} />
      </div>
      <div style={{ display: "flex", gap: 12, marginTop: 44 }}>
        {PILLS.map((p, i) => {
          const t = spr(f, T.pills + i * 5, { damping: 14, stiffness: 180 });
          return (
            <span
              key={p.text}
              style={{
                display: "inline-flex",
                alignItems: "center",
                gap: 9,
                padding: "12px 18px",
                borderRadius: 99,
                background: i === 0 ? C.navy : "rgba(255,255,255,0.9)",
                color: i === 0 ? "#fff" : C.ink,
                border: i === 0 ? "none" : `1px solid ${C.hairline}`,
                fontSize: 20,
                fontWeight: 500,
                opacity: Math.min(1, t * 1.6),
                transform: `translateY(${(1 - t) * 24}px) scale(${0.85 + 0.15 * t})`,
              }}
            >
              <Icon name={p.icon} size={18} stroke={2.2} />
              {p.text}
            </span>
          );
        })}
      </div>
      <p style={{ margin: "36px 0 0", fontSize: 20, color: C.subtle, letterSpacing: "0.02em", opacity: range(f, T.pills + 22, T.pills + 34) }}>ai-commerce-hack.vercel.app</p>
    </div>
  );
};

const Phone: React.FC<{ f: number }> = ({ f }) => {
  const cam = camera(f);
  return (
    <AbsoluteFill style={{ perspective: 2400 }}>
      <div
        style={{
          position: "absolute",
          left: cam.cx - PHONE_W / 2,
          top: cam.cy - PHONE_H / 2,
          width: PHONE_W,
          height: PHONE_H,
          opacity: range(f, 0, 6),
          transform: `rotateY(${cam.rotY}deg) rotateX(${cam.rotX}deg) scale(${cam.s})`,
          transformStyle: "preserve-3d",
        }}
      >
        <IPhone>
          <Screen />
        </IPhone>
      </div>
    </AbsoluteFill>
  );
};

const DUCK = (() => {
  const out = new Float32Array(DURATION + 1);
  let d = 0;
  for (let f = 0; f <= DURATION; f++) {
    const target = voiceAt(f) || voiceAt(f + 5) ? 1 : 0;
    d += (target - d) * (target > d ? 0.3 : 0.07);
    out[f] = d;
  }
  return out;
})();

const SFX: Array<{ at: number; src: string; volume: number }> = [
  { at: 0, src: "whoosh", volume: 0.3 },
  { at: T.morph - 6, src: "whoosh", volume: 0.18 },
  ...Object.values(T.add).map((at) => ({ at, src: "pop", volume: 0.42 })),
  { at: T.inStore, src: "pop", volume: 0.3 },
  { at: T.oos, src: "alert", volume: 0.42 },
  { at: T.swapIn, src: "pop", volume: 0.45 },
  { at: T.pushIn + 2, src: "whoosh", volume: 0.28 },
  { at: T.dairy, src: "pop", volume: 0.22 },
  { at: T.tap, src: "pop", volume: 0.5 },
  { at: T.tap + 2, src: "chime", volume: 0.5 },
  { at: T.outro, src: "whoosh", volume: 0.32 },
  { at: T.wordmark, src: "chime", volume: 0.2 },
];

const Soundtrack: React.FC = () => (
  <>
    <Audio
      src={staticFile("music/bed.mp3")}
      volume={(f) => (0.3 - 0.19 * DUCK[Math.min(DURATION, f)]) * range(f, 0, 10, 0, 1, (x) => x) * (1 - range(f, 868, 899, 0, 1, (x) => x))}
    />
    {LINES.map((l) => (
      <Sequence key={l.id} from={l.at} layout="none">
        <Audio src={staticFile(`voice/${l.id}.wav`)} />
      </Sequence>
    ))}
    {SFX.map((s, i) => (
      <Sequence key={i} from={s.at} durationInFrames={45} layout="none">
        <Audio src={staticFile(`sfx/${s.src}.wav`)} volume={s.volume} />
      </Sequence>
    ))}
  </>
);

export const Demo: React.FC = () => {
  const f = useCurrentFrame();
  return (
    <AbsoluteFill style={{ fontFamily: sans, color: C.ink, overflow: "hidden" }}>
      <Backdrop f={f} />
      <BigType f={f} />
      <Ripple f={f} at={T.tap + 2} />
      <Headline f={f} />
      <Subtitles f={f} />
      <Outro f={f} />
      <Phone f={f} />
      <Callouts f={f} />
      <Soundtrack />
    </AbsoluteFill>
  );
};

