import { Audio } from "@remotion/media";
import { createContext, useContext } from "react";
import { AbsoluteFill, Sequence, staticFile, useCurrentFrame } from "remotion";
import { Orb, orbLevel } from "./orb";
import { IPhone, SH, SW, SWAP_FOCUS, Screen } from "./phone";
import { DURATION, LINES, T, ease, lerp, lineEnd, range, spr, voiceAt, wordsSpoken } from "./timeline";
import { C, Icon, sans, serif } from "./ui";

const PHONE_W = SW + 32;
const PHONE_H = SH + 32;

type Align = "left" | "center";
type Layout = {
  w: number;
  h: number;
  base: { cx: number; cy: number; s: number };
  rot: [number, number];
  zoom: number;
  focus: { x: number; y: number };
  outro: { cx: number; cy: number; s: number; rotY: number; rotX: number };
  headline: { left: number; top: number; width: number; size: number; align: Align };
  subs: { left: number; top: number; width: number; size: number; align: Align };
  callouts: boolean;
  lockup: { left: number; top: number; width: number; align: Align; word: number; tag: number; orb: number };
  big: { top: number; size: number };
};

const WIDE: Layout = {
  w: 1920,
  h: 1080,
  base: { cx: 1200, cy: 540, s: 1.06 },
  rot: [-9, -2],
  zoom: 1.36,
  focus: { x: 1150, y: 560 },
  outro: { cx: 1330, cy: 540, s: 0.98, rotY: -16, rotX: 3 },
  headline: { left: 140, top: 262, width: 720, size: 96, align: "left" },
  subs: { left: 140, top: 630, width: 640, size: 36, align: "left" },
  callouts: true,
  lockup: { left: 140, top: 250, width: 900, align: "left", word: 176, tag: 64, orb: 128 },
  big: { top: 120, size: 620 },
};

const TALL: Layout = {
  w: 1080,
  h: 1920,
  base: { cx: 540, cy: 1080, s: 1.28 },
  rot: [-6, 0],
  zoom: 1.12,
  focus: { x: 540, y: 1100 },
  outro: { cx: 540, cy: 1440, s: 0.88, rotY: 0, rotX: 12 },
  headline: { left: 60, top: 128, width: 960, size: 86, align: "center" },
  subs: { left: 70, top: 1688, width: 940, size: 34, align: "center" },
  callouts: false,
  lockup: { left: 60, top: 250, width: 960, align: "center", word: 150, tag: 62, orb: 112 },
  big: { top: 700, size: 400 },
};

const LayoutCtx = createContext<Layout>(WIDE);
const useLayout = () => useContext(LayoutCtx);

function camera(f: number, L: Layout) {
  const entry = spr(f, 0, { damping: 200 }, 34);
  const pIn = spr(f, T.pushIn, { damping: 200 }, 40) * (1 - spr(f, T.pullBack, { damping: 200 }, 34));
  const pOut = spr(f, T.outro, { damping: 200 }, 46);
  const zs = L.base.s * L.zoom;
  const focusDy = (16 + SWAP_FOCUS.y - PHONE_H / 2) * zs;
  let s = lerp(L.base.s, zs, pIn);
  let cx = lerp(L.base.cx, L.focus.x, pIn);
  let cy = lerp(L.base.cy, L.focus.y - focusDy, pIn);
  s = lerp(s, L.outro.s, pOut);
  cx = lerp(cx, L.outro.cx, pOut);
  cy = lerp(cy, L.outro.cy, pOut);
  const shake = f >= T.oos ? Math.sin(f * 2.4) * 8 * (1 - range(f, T.oos, T.oos + 16, 0, 1, (x) => x)) : 0;
  const bump = 1 + 0.025 * Math.sin(Math.PI * range(f, T.tap + 1, T.tap + 16, 0, 1, (x) => x));
  const rotY = lerp(L.rot[0], L.rot[1], range(f, 0, 280)) * (1 - pIn) * (1 - pOut) + L.outro.rotY * pOut + Math.sin(f / 55) * 1.4;
  const rotX = lerp(26, 4, entry) * (1 - pIn) * (1 - pOut) + L.outro.rotX * pOut;
  return {
    cx: cx + shake,
    cy: cy + (1 - entry) * 620 + Math.sin(f / 38) * 5,
    s: s * bump * lerp(0.92, 1, entry),
    rotY,
    rotX,
    entry,
  };
}

const Backdrop: React.FC<{ f: number }> = ({ f }) => {
  const L = useLayout();
  const cam = camera(f, L);
  const lv = orbLevel(f);
  const kx = L.w / 1920;
  const ky = L.h / 1080;
  const oosFlash = f >= T.oos ? range(f, T.oos, T.oos + 3) * (1 - range(f, T.oos + 6, T.oos + 40)) : 0;
  const blob = (x: number, y: number, r: number, color: string, k: number) => (
    <div
      style={{
        position: "absolute",
        left: x * kx + Math.sin(f / (60 + k * 7) + k) * 60 - r,
        top: y * ky + Math.cos(f / (70 + k * 5) + k) * 50 - r,
        width: r * 2,
        height: r * 2,
        borderRadius: "50%",
        background: `radial-gradient(circle, ${color} 0%, rgba(255,255,255,0) 68%)`,
      }}
    />
  );
  return (
    <AbsoluteFill style={{ background: "linear-gradient(180deg,#e9eef6 0%,#f3f5f8 55%,#f7f7f8 100%)", overflow: "hidden" }}>
      {blob(1500, 200, 620, "rgba(150,200,255,0.55)", 1)}
      {blob(260, 900, 640, "rgba(204,184,250,0.42)", 2)}
      {blob(900, -120, 520, "rgba(238,204,245,0.35)", 3)}
      <AbsoluteFill
        style={{
          backgroundImage: "radial-gradient(rgba(11,31,91,0.10) 1.1px, transparent 1.4px)",
          backgroundSize: "30px 30px",
          backgroundPosition: `${(f * 0.25) % 30}px ${(f * 0.12) % 30}px`,
          maskImage: "radial-gradient(ellipse 70% 70% at 55% 50%, black 0%, transparent 75%)",
          WebkitMaskImage: "radial-gradient(ellipse 70% 70% at 55% 50%, black 0%, transparent 75%)",
        }}
      />
      <div
        style={{
          position: "absolute",
          left: cam.cx - 520,
          top: cam.cy - 520,
          width: 1040,
          height: 1040,
          borderRadius: "50%",
          background: "radial-gradient(circle, rgba(48,110,255,0.32) 0%, rgba(120,170,255,0.12) 38%, rgba(255,255,255,0) 66%)",
          opacity: (0.35 + 0.65 * lv) * cam.entry,
          transform: `scale(${0.9 + lv * 0.18})`,
        }}
      />
      <AbsoluteFill style={{ background: `radial-gradient(circle at ${cam.cx}px ${cam.cy}px, rgba(220,40,30,0.22) 0%, rgba(220,40,30,0) 55%)`, opacity: oosFlash }} />
    </AbsoluteFill>
  );
};

const BigType: React.FC<{ f: number }> = ({ f }) => {
  const L = useLayout();
  const o = range(f, T.swapIn, T.swapIn + 14) * (1 - range(f, T.pullBack - 10, T.pullBack + 6));
