const DUCK = (() => {
  const out = new Float32Array(DURATION + 1);
  let d = 0;
  for (let f = 0; f <= DURATION; f++) {
    const target = voiceAt(f) || voiceAt(f + 5) ? 1 : 0;
    d += (target - d) * (target > d ? 0.3 : 0.07);
    out[f] = d;
  }
  return out;
})();

